#[path="../../rust/crates/genewars-runtime/src/terrain_target.rs"]mod target;
use std::{fs,io::{BufWriter,Write},path::Path};
fn main(){let d=std::env::args().nth(1).unwrap();let p=Path::new(&d);let map=fs::read(p.join("map.bin")).unwrap();let mut out=BufWriter::new(fs::File::create(p.join("target-output.bin")).unwrap());
 for b in fs::read(p.join("target-input.bin")).unwrap().chunks_exact(8){let c=[u16::from_le_bytes(b[0..2].try_into().unwrap()),u16::from_le_bytes(b[2..4].try_into().unwrap())];let s=[u16::from_le_bytes(b[4..6].try_into().unwrap())as i32,u16::from_le_bytes(b[6..8].try_into().unwrap())as i32];let mut r=[0;9];match target::project_terrain_target(&map,c,s){Ok(v)=>{r[0]=1;r[1..3].copy_from_slice(&v.point[0].to_le_bytes());r[3..5].copy_from_slice(&v.point[1].to_le_bytes());r[5..7].copy_from_slice(&v.cell_index.to_le_bytes());r[7]=v.strip_pair;r[8]=match v.triangle{target::TerrainTargetTriangle::First=>0,target::TerrainTargetTriangle::Second=>1};},Err(target::TerrainTargetError::NoIntersection)=>{},Err(e)=>panic!("unexpected {e:?}")};out.write_all(&r).unwrap();}out.flush().unwrap();}
